        var result = await sut.CreateAsync(_boardId, _laneId,
            new CreateCardRequest("Card With Details", "Some description", dueDate));

        result.Description.Should().Be("Some description");
        result.DueDate.Should().Be(dueDate);
    }

    // ── Update ────────────────────────────────────────────────────────────────

